.tool-page{max-width:850px;margin:38px auto;padding:0 18px}.tool-panel{padding:clamp(20px,5vw,36px);border:1px solid #e2e9f8;border-radius:24px;background:#fff;box-shadow:0 14px 38px #1e3a8a0b}.tool-panel h1{margin:10px 0;color:#172554;font-size:clamp(1.8rem,6vw,2.5rem)}.tool-panel .intro{color:#71809a;line-height:1.8}.tool-label{display:block;margin:20px 0 8px;font-weight:800;color:#34466b}.tool-textarea{display:block;width:100%;min-height:220px;padding:16px;border:1px solid #dbe4f4;border-radius:15px;background:#f9fbff;color:#1e293b;font:inherit;line-height:1.7;resize:vertical}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.stat{padding:15px 12px;border-radius:14px;background:#eef4ff;text-align:center}.stat b{display:block;color:#315eea;font-size:1.5rem}.stat span{font-size:.77rem;color:#71809a}.tool-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.tool-actions button,.tool-back{border:0;border-radius:11px;padding:12px 16px;background:#315eea;color:white;font:inherit;font-weight:800;cursor:pointer;text-decoration:none}.tool-actions .secondary{background:#eef2ff;color:#315eea}.dark .tool-panel{background:#111c34;border-color:#263652}.dark .tool-panel h1,.dark .tool-label{color:#e5edff}.dark .tool-textarea{background:#0b1428;border-color:#2b3b58;color:#e5edff}.dark .stat{background:#1b2d50}.dark .stat span{color:#aab8d4}@media(max-width:500px){.stat-grid{gap:7px}.stat{padding:12px 5px}.stat b{font-size:1.25rem}.stat span{font-size:.69rem}}
