const input=document.getElementById('textInput');function count(){const t=input.value.trim();document.getElementById('words').textContent=t?t.split(/\s+/u).length:0;document.getElementById('chars').textContent=input.value.length;document.getElementById('sentences').textContent=t?(t.match(/[.!?।]+(?=\s|$)/gu)||[]).length:0;}input.addEventListener('input',count);document.getElementById('clearBtn').addEventListener('click',()=>{input.value='';count();input.focus();});document.getElementById('copyBtn').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(input.value);document.getElementById('copyBtn').textContent='কপি হয়েছে ✓';}catch(e){input.select();document.execCommand('copy');document.getElementById('copyBtn').textContent='কপি চেষ্টা সম্পন্ন';}});
</script><script src="/assets/language.js" defer></script></body></html>